{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "A velocidade é constante, então a distância é proporcional ao tempo. Chame de v a distância andada em 1 hora: 4 h dão 4v e 2 h dão 2v. O trecho de 2 h para o leste existe nas duas rotas, então ele não muda a diferença entre os pontos finais. Por isso T→R tem o mesmo tamanho e a mesma direção de S→Q.",
   "motivo": "Texto mais claro: explica por que os trechos iguais se cancelam, sem a palavra 'deslocamento' ambígua."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["direção 90, 180, 270, 0", "ângulo da bússola contado a partir do Norte (0), girando no sentido horário: 90 = Leste, 180 = Sul, 270 = Oeste"],
    ["v", "distância percorrida em 1 hora (velocidade constante)"],
    ["cos", "cosseno de um ângulo, número que a prova dá (cos 50° ≈ 0,64)"],
    ["lei dos cossenos", "regra que dá o terceiro lado de um triângulo quando se conhecem dois lados e o ângulo entre eles"],
    ["ângulo obtuso", "ângulo maior que 90°; seu cosseno é negativo"],
    ["sudeste", "direção entre o Leste (90) e o Sul (180), ou seja, 135"]
   ],
   "motivo": "Termos técnicos usados na resolução (lei dos cossenos, obtuso, sudeste) não estavam explicados."
  },
  {
   "campo": "resolucao.passos[0].porque",
   "depois": "PQ aponta para 110 e PS aponta para 340. A diferença é 230°, mas o ângulo entre duas retas que saem de P é o menor giro: 360° − 230° = 130°.",
   "motivo": "Explica por que se usa 360 − 230."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "R = Q + 2v (leste)",
   "motivo": "Linha curta para caber na tela; segunda parte vai ao porque."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "T = S + 2v (leste) também. R e T ficam 2v a leste de Q e de S. Logo T→R é igual a S→Q (mesmo tamanho, mesma direção), e basta achar SQ no triângulo PSQ.",
   "motivo": "Une as duas relações que antes estavam em uma só linha comprida."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "SQ² = 16v² + 16v² − 32v²·cos130°",
   "motivo": "Mais curto e já com as contas feitas; coerente com o quadro."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "SQ² = 32v² · 1,64 = 52,48v²",
   "motivo": "Cabe na tela e mostra o valor intermediário."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "cos130° = − cos50° = − 0,64. Então − 32v²·(− 0,64) vira + 32v²·0,64, e SQ² = 32v²·(1 + 0,64). Daí SQ ≈ 7,24v.",
   "motivo": "Mostra o sinal passo a passo."
  },
  {
   "campo": "resolucao.passos[4].conta",
   "depois": "t = 7,24v ÷ v = 7,24 h",
   "motivo": "Conta curta; o resto vai ao porque."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "Com v constante, distância 7,24v leva 7,24 h. A parte 0,24 h vale 0,24 × 60 ≈ 15 min. Então o tempo é cerca de 7 h 15 min.",
   "motivo": "Simplifica a conversão em minutos."
  },
  {
   "campo": "resolucao.passos[5].conta",
   "depois": "R abaixo e à direita de T → 135",
   "motivo": "Cabe em ~30 caracteres."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "A direção 135 está certa, mas 6 h não confere. 6 h é o tempo da rota planejada (4 + 2), não o da correção. SQ vale 7,24v, e não 6v, porque o ângulo é 130° e cos130° = −0,64.",
   "motivo": "Frase mais curta e sem a conta invertida confusa."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "A direção 135 está certa, mas 12 h não confere. SQ ≈ 7,24v pede cerca de 7,24 h. Dois lados de 4v não podem dar um terceiro maior que 4v + 4v = 8v, então 12 h é impossível.",
   "motivo": "Explica a desigualdade triangular em linguagem simples."
  },
  {
   "campo": "resolucao.checagem",
   "depois": "Por componentes: T→R vale 4v·(cos20° + sen20°) para leste e o mesmo valor para o sul. Com cos20° ≈ 0,94 e sen20° ≈ 0,34, cada componente é 4v·1,28 ≈ 5,12v. A distância é 5,12v·√2 ≈ 7,24v. Fecha, e as componentes iguais confirmam 135.",
   "motivo": "Troca o símbolo ·(…) ambíguo por texto mais claro."
  },
  {
   "campo": "resolucao.armadilha",
   "depois": "Esquecer que cos130° é negativo: com o sinal errado, SQ² = 32v²·(1 − 0,64) = 11,52v², e SQ ≈ 3,4v, muito abaixo de 7 h.",
   "motivo": "Mostra a conta completa do erro."
  },
  {
   "campo": "resolucao.quadro",
   "depois": [
    {"linha": "ângulo em P = 130°", "nota": "360° − (340° − 110°)"},
    {"linha": "TR = SQ", "nota": "os 2v para leste são iguais"},
    {"linha": "SQ² = 16v² + 16v² − 32v²·cos130°", "nota": "lei dos cossenos em PSQ"},
    {"linha": "cos130° = − cos50° = − 0,64", "nota": "ângulo obtuso: cosseno negativo"},
    {"linha": "SQ² = 32v² + 32v²·0,64", "nota": "menos com menos vira mais"},
    {"linha": "SQ² = 32v² · 1,64", "nota": "32v² em evidência", "destaque": "1,64"},
    {"linha": "SQ² = 52,48v²", "nota": "32 × 1,64 = 52,48"},
    {"linha": "SQ ≈ 7,24v", "nota": "raiz de 52,48"},
    {"linha": "t = 7,24v ÷ v = 7,24 h", "nota": "o v cancela"},
    {"linha": "0,24 h × 60 ≈ 15 min", "nota": "tempo: 7 h 15 min"}
   ],
   "motivo": "Quadro com passagens sem pulo: separa o termo com sinal e a evidência."
  }
 ],
